_TRANSPORT_HELPER = '#!/usr/bin/env python3\n"""Deterministically add tiny centre clearance to long-decimal packing cases.\n\nOnly centres move; angles and unit side lengths are unchanged. This creates a\nnew candidate which must still pass raw and numeric-roundtrip validation.\nThe helper is stdlib-only so the same implementation can run on Kaggle.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport csv\nfrom decimal import Decimal, ROUND_HALF_EVEN, localcontext\nimport hashlib\nimport json\nfrom pathlib import Path\n\nDEFAULT_FACTOR = "1.00000000001"\nPRECISION = 100\nLONG_DECIMAL_LENGTH = 50\n\n\ndef file_sha256(path: Path) -> str:\n    with path.open("rb") as stream:\n        return hashlib.file_digest(stream, "sha256").hexdigest()\n\n\ndef make_transport_safe(source: Path, target: Path, factor: str = DEFAULT_FACTOR) -> dict:\n    source, target = Path(source), Path(target)\n    if source.resolve() == target.resolve():\n        raise ValueError("source and target must differ; preserve the raw candidate")\n    source_hash = file_sha256(source)\n    with source.open(newline="") as stream:\n        reader = csv.DictReader(stream)\n        fieldnames = reader.fieldnames\n        if fieldnames is None or not {"id", "n", "square_id", "x", "y", "angle"}.issubset(fieldnames):\n            raise ValueError("missing submission columns")\n        rows = list(reader)\n    selected = {int(row["n"]) for row in rows\n                if any(len(row[key]) > LONG_DECIMAL_LENGTH for key in ("x", "y", "angle"))}\n    changed_rows = 0\n    with localcontext() as ctx:\n        ctx.prec = PRECISION\n        ctx.rounding = ROUND_HALF_EVEN\n        multiplier = Decimal(factor)\n        if not multiplier.is_finite() or multiplier <= 1:\n            raise ValueError("factor must be a finite decimal greater than one")\n        for row in rows:\n            if int(row["n"]) in selected:\n                row["x"] = str(Decimal(row["x"]) * multiplier)\n                row["y"] = str(Decimal(row["y"]) * multiplier)\n                changed_rows += 1\n    target.parent.mkdir(parents=True, exist_ok=True)\n    temporary = target.with_suffix(target.suffix + ".part")\n    with temporary.open("w", newline="") as stream:\n        writer = csv.DictWriter(stream, fieldnames=fieldnames)\n        writer.writeheader()\n        writer.writerows(rows)\n    if file_sha256(source) != source_hash:\n        raise RuntimeError("source changed during conversion")\n    temporary.replace(target)\n    return {"source": str(source), "source_sha256": source_hash,\n            "output": str(target), "sha256": file_sha256(target),\n            "factor": factor, "decimal_precision": PRECISION,\n            "decimal_rounding": "ROUND_HALF_EVEN", "length_threshold": LONG_DECIMAL_LENGTH,\n            "selected_cases": sorted(selected), "selected_count": len(selected),\n            "changed_rows": changed_rows, "rows": len(rows)}\n\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("source", type=Path)\n    parser.add_argument("target", type=Path)\n    parser.add_argument("--factor", default=DEFAULT_FACTOR)\n    parser.add_argument("--report", type=Path)\n    args = parser.parse_args()\n    result = make_transport_safe(args.source, args.target, args.factor)\n    report = args.report or args.target.with_suffix(".transport-transform.json")\n    report.write_text(json.dumps(result, indent=2) + "\\n")\n    print(json.dumps({k: v for k, v in result.items() if k != "selected_cases"}, indent=2))\n\n\nif __name__ == "__main__":\n    main()\n'
assert _source_sha(_TRANSPORT_HELPER.encode())==SAFE_PORTFOLIO_MANIFEST['transport_transform']['helper_sha256']
_transport_namespace={'__name__':'portfolio_transport_helper','__file__':'make_transport_safe.py'}
exec(compile(_TRANSPORT_HELPER,'make_transport_safe.py','exec'),_transport_namespace)

def reconstruct_portfolio(destination,cache_dir=None):
    destination=Path(destination)
    if destination.is_file():
        assert _source_sha(destination.read_bytes())==SAFE_PORTFOLIO_MANIFEST['csv_sha256']
        return destination
    cache=Path(cache_dir) if cache_dir is not None else Path('/tmp/squares-portfolio-source-cache')
    cache.mkdir(parents=True,exist_ok=True)
    raw=cache/('raw-'+PORTFOLIO_MANIFEST['csv_sha256']+'.csv')
    _reconstruct_raw_portfolio(raw,cache)
    transformed=_transport_namespace['make_transport_safe'](raw,destination,
        SAFE_PORTFOLIO_MANIFEST['transport_transform']['factor'])
    assert transformed['source_sha256']==SAFE_PORTFOLIO_MANIFEST['raw_csv_sha256']
    assert transformed['sha256']==SAFE_PORTFOLIO_MANIFEST['csv_sha256']
    assert destination.stat().st_size==SAFE_PORTFOLIO_MANIFEST['csv_bytes']
    (destination.parent/'transport_transform.json').write_text(json.dumps(transformed,indent=2)+'\n')
    print(json.dumps({'stage':'transport_safe_portfolio_reconstructed','sha256':transformed['sha256'],
        'score':SAFE_PORTFOLIO_MANIFEST['official_score'],'rows':transformed['rows'],
        'selected_cases':transformed['selected_count']}),flush=True)
    return destination

EXPORT_MANIFEST = SAFE_PORTFOLIO_MANIFEST

if __name__=='__main__':
    import argparse
    parser=argparse.ArgumentParser()
    parser.add_argument('--cache-dir')
    parser.add_argument('--destination',default='/kaggle/working/submission.csv')
    args=parser.parse_args()
    output=reconstruct_portfolio(Path(args.destination),args.cache_dir)
    (output.parent/'export_manifest.json').write_text(json.dumps(EXPORT_MANIFEST,indent=2)+'\n')
